it('creates user with sanitized name and lowercase email', async () => {
  const input = { email: 'John@Example.COM', name: '<script>alert("xss")</script>John' };
  const user = await createUser(input);
  expect(user.email).toBe('john@example.com');
  expect(user.name).toBe('&lt;script&gt;alert(&quot;xss&quot;)&lt;/script&gt;John');
  expect(user.id).toMatch(/^user_\d+_[a-z0-9]{7}$/);
  expect(user.createdAt).toBeInstanceOf(Date);
});

it('validates correct email formats', () => {
  expect(isValidEmail('user@example.com')).toBe(true);
  expect(isValidEmail('user.name+tag@example.co.uk')).toBe(true);
});

it('rejects invalid email formats', () => {
  expect(isValidEmail('notanemail')).toBe(false);
  expect(isValidEmail('@example.com')).toBe(false);
  expect(isValidEmail('user@')).toBe(false);
  expect(isValidEmail('user@domain')).toBe(false);
  expect(isValidEmail('')).toBe(false);
});

it('escapes HTML special characters to prevent XSS', () => {
  expect(sanitizeInput('<script>alert("xss")</script>')).toBe('&lt;script&gt;alert(&quot;xss&quot;)&lt;/script&gt;');
  expect(sanitizeInput("<img src='x' onerror='alert(1)'>")).toBe('&lt;img src=&#039;x&#039; onerror=&#039;alert(1)&#039;&gt;');
  expect(sanitizeInput('Normal text')).toBe('Normal text');
});

it('handles edge cases in email validation', () => {
  expect(isValidEmail(' user@example.com')).toBe(false);
  expect(isValidEmail('user@example.com ')).toBe(false);
  expect(isValidEmail('user name@example.com')).toBe(false);
});

it('handles empty and Unicode input in sanitization', () => {
  expect(sanitizeInput('')).toBe('');
  expect(sanitizeInput('Hello 世界 🌍')).toBe('Hello 世界 🌍');
});

it('generates unique IDs with correct format', () => {
  const id1 = generateId();
  const id2 = generateId();
  expect(id1).toMatch(/^user_\d+_[a-z0-9]{7}$/);
  expect(id2).toMatch(/^user_\d+_[a-z0-9]{7}$/);
  expect(id1).not.toBe(id2);
});

